package org.marketreview.nativeapp;
import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;
public final class LocalCandidateBackgroundAdapterChecks {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static JSONObject read(String p)throws Exception{return new JSONObject(new String(Files.readAllBytes(Paths.get(p)),StandardCharsets.UTF_8));}
 public static void main(String[]args)throws Exception {JSONObject fixtures=read(args[0]),baseline=null;JSONArray cases=fixtures.getJSONArray("cases"),outputs=new JSONArray();int good=0,rejected=0;for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i),input=c.getJSONObject("input"),result=null;boolean threw=false;try{result=LocalCandidateBackgroundAdapter.freeze(input);}catch(Exception e){threw=true;}check(threw==c.getBoolean("reject"),c.getString("name")+" rejection mismatch");if(threw){outputs.put(new JSONObject().put("name",c.getString("name")).put("rejected",true));rejected++;continue;}good++;LocalCandidateBackgroundAdapter.verify(result);check(LocalCandidateBackgroundAdapter.canonical(result.get("input")).equals(LocalCandidateBackgroundAdapter.canonical(input)),"actual input frozen");JSONObject expected=c.getJSONObject("expected"),backgrounds=result.getJSONObject("backgrounds");java.util.Iterator<String>ids=expected.keys();while(ids.hasNext()){String id=ids.next();JSONObject states=expected.getJSONObject(id);java.util.Iterator<String>keys=states.keys();while(keys.hasNext()){String key=keys.next();check(backgrounds.getJSONObject(id).getJSONObject(key).getString("status").equals(states.getString(key)),c.getString("name")+" "+key);}}ids=backgrounds.keys();while(ids.hasNext()){String id=ids.next();JSONObject e=LocalCandidateBackground.evaluate(backgrounds.getJSONObject(id),id,"stable",Instant.parse(input.getString("capturedAt")));check(e.has("knownDelta"),"v38 accepts projection");}
 JSONObject bg=backgrounds.getJSONObject("SH:stock:600001");String name=c.getString("name");if(name.equals("actual-native-fields")){baseline=result;JSONObject h=bg.getJSONObject("holdings").getJSONArray("items").getJSONObject(0);check(h.getString("businessAsOf").equals("2026-10-12")&&h.getString("observedAt").equals(input.getString("capturedAt")),"observation did not replace business time");check(bg.getJSONObject("recent").getJSONArray("items").getJSONObject(0).getString("viewedAt").equals("2026-10-13T07:00:00.000Z"),"original view time retained");check(bg.getJSONObject("leaders").getJSONArray("items").getJSONObject(0).getString("configUpdatedAt").equals("2026-10-12T04:00:00.000Z"),"configuration date retained");}if(name.equals("rank81-not-recent")||name.equals("native-full-market-no-guess"))check(bg.getJSONObject("recent").getJSONArray("items").length()==0,"no rank/backfill/market inference");if(name.equals("ledger-business-time-blank")||name.equals("ledger-business-time-null"))check(bg.getJSONObject("holdings").getJSONArray("items").getJSONObject(0).isNull("businessAsOf"),"unknown business time not filled");outputs.put(new JSONObject().put("name",name).put("result",result));}
 JSONArray legacy=read(args[2]).getJSONArray("cases");JSONObject stock=null;for(int i=0;i<legacy.length();i++){JSONObject c=legacy.getJSONObject(i);if(c.has("error"))continue;JSONArray rows=c.getJSONObject("result").getJSONArray("rows");if(rows.length()>0&&rows.getJSONObject(0).opt("rawScore") instanceof Number){stock=new JSONObject(c.getJSONArray("selected").getJSONObject(0).toString());break;}}check(stock!=null&&baseline!=null,"composition fixtures");stock.put("id","SH:stock:600001").put("symbol","sh600001");Instant cut=Instant.parse(baseline.getJSONObject("input").getString("capturedAt"));JSONObject v1=LocalCandidateModel.evaluate(LocalCandidateModel.snapshot(new JSONArray().put(stock),"stable",cut));stock.put("backgroundInput",baseline.getJSONObject("backgrounds").getJSONObject("SH:stock:600001"));JSONObject v2=LocalCandidateModel.evaluate(LocalCandidateModel.snapshot(new JSONArray().put(stock),"stable",cut));LocalCandidateModel.verify(v2);JSONObject a=v1.getJSONArray("rows").getJSONObject(0),b=v2.getJSONArray("rows").getJSONObject(0);check(LocalCandidateModel.canonical(a.get("factors")).equals(LocalCandidateModel.canonical(b.get("factors")))&&b.getInt("rawScore")==a.getInt("rawScore")+30,"technical model plus known30 only");check(b.getJSONObject("backgroundEvaluation").isNull("completeDelta"),"theme/demand unknown");JSONObject bad=new JSONObject(baseline.toString()).put("inputHash","tampered");boolean failed=false;try{LocalCandidateBackgroundAdapter.verify(bad);}catch(Exception e){failed=true;}check(failed,"tamper rejected");JSONObject original=new JSONObject(baseline.getJSONObject("input").toString()),frozen=LocalCandidateBackgroundAdapter.freeze(original);original.put("mode","changed-after-freeze");LocalCandidateBackgroundAdapter.verify(frozen);Thread.currentThread().interrupt();failed=false;try{LocalCandidateBackgroundAdapter.freeze(frozen.getJSONObject("input"));}catch(InterruptedException e){failed=true;}finally{Thread.interrupted();}check(failed,"cancelled");Files.write(Paths.get(args[1]),outputs.toString().getBytes(StandardCharsets.UTF_8));System.out.println("PASS JVM adapter "+good+" converted, "+rejected+" rejected; frozen hash/roundtrip, v38 composition, technical factors unchanged");
 }
}

